-- Run only on an isolated database with the reviewed migration installed.
begin;
select extensions.plan(24);
select extensions.ok((select relrowsecurity from pg_class where oid='public.class_creation_permissions'::regclass), 'Creation override table has RLS');
select extensions.ok(not has_table_privilege('anon','public.class_creation_permissions','SELECT'), 'anon has no direct SELECT on overrides');
select extensions.ok(not has_table_privilege('anon','public.class_creation_permissions','INSERT'), 'anon has no direct INSERT on overrides');
select extensions.ok(not has_table_privilege('anon','public.class_creation_permissions','UPDATE'), 'anon has no direct UPDATE on overrides');
select extensions.ok(not has_table_privilege('anon','public.class_creation_permissions','DELETE'), 'anon has no direct DELETE on overrides');
select extensions.ok(not has_table_privilege('authenticated','public.class_creation_permissions','SELECT'), 'authenticated has no direct SELECT on overrides');
select extensions.ok(not has_table_privilege('authenticated','public.class_creation_permissions','INSERT'), 'authenticated has no direct INSERT on overrides');
select extensions.ok(not has_table_privilege('authenticated','public.class_creation_permissions','UPDATE'), 'authenticated has no direct UPDATE on overrides');
select extensions.ok(not has_table_privilege('authenticated','public.class_creation_permissions','DELETE'), 'authenticated has no direct DELETE on overrides');
select extensions.ok(not has_schema_privilege('authenticated','private','USAGE'), 'Clients cannot enter private helper schema');
select extensions.ok(not has_function_privilege('authenticated','private.class_creation_permission(uuid)','EXECUTE'), 'Clients cannot probe arbitrary user permission helper');
select extensions.ok(not has_function_privilege('anon','public.get_my_class_creation_permission()','EXECUTE'), 'Anonymous cannot execute get_my_class_creation_permission()');
select extensions.ok(has_function_privilege('authenticated','public.get_my_class_creation_permission()','EXECUTE'), 'Authenticated can reach guarded get_my_class_creation_permission()');
select extensions.ok(not has_function_privilege('anon','public.list_academic_years()','EXECUTE'), 'Anonymous cannot execute list_academic_years()');
select extensions.ok(has_function_privilege('authenticated','public.list_academic_years()','EXECUTE'), 'Authenticated can reach guarded list_academic_years()');
select extensions.ok(not has_function_privilege('anon','public.governance_list_class_creation_permissions(integer,integer)','EXECUTE'), 'Anonymous cannot execute governance_list_class_creation_permissions(integer,integer)');
select extensions.ok(has_function_privilege('authenticated','public.governance_list_class_creation_permissions(integer,integer)','EXECUTE'), 'Authenticated can reach guarded governance_list_class_creation_permissions(integer,integer)');
select extensions.ok(not has_function_privilege('anon','public.governance_set_class_creation_permission(uuid,boolean,text,integer)','EXECUTE'), 'Anonymous cannot execute governance_set_class_creation_permission(uuid,boolean,text,integer)');
select extensions.ok(has_function_privilege('authenticated','public.governance_set_class_creation_permission(uuid,boolean,text,integer)','EXECUTE'), 'Authenticated can reach guarded governance_set_class_creation_permission(uuid,boolean,text,integer)');
select extensions.ok(not has_function_privilege('anon','public.create_school_class(text,text,text,integer,text)','EXECUTE'), 'Anonymous cannot create classes');
select extensions.ok((select proconfig @> array['search_path=pg_catalog, public'] from pg_proc where oid='public.create_school_class(text,text,text,integer,text)'::regprocedure), 'Create uses fixed safe search path');
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{}',true);
select extensions.throws_ok($$select public.get_my_class_creation_permission()$$,'P0001','actor_unauthenticated','Identityless authenticated role denied get_my_class_creation_permission()');
select extensions.throws_ok($$select public.list_academic_years()$$,'P0001','actor_unauthenticated','Identityless authenticated role denied list_academic_years()');
select extensions.throws_ok($$select public.governance_list_class_creation_permissions()$$,'P0001','actor_unauthenticated','Identityless authenticated role denied governance_list_class_creation_permissions()');
reset role;
select * from extensions.finish();
rollback;
